CREATE TABLE category (id uuid PRIMARY KEY, source_key text UNIQUE, name text NOT NULL, slug text NOT NULL UNIQUE, parent_id uuid REFERENCES category(id), description text NOT NULL DEFAULT '');
CREATE TABLE product (id uuid PRIMARY KEY, source_key text UNIQUE, title text NOT NULL, slug text NOT NULL UNIQUE, description_html text NOT NULL DEFAULT '', status text NOT NULL CHECK (status IN ('draft','published','archived')), sku text UNIQUE, price_cop numeric(14,2) CHECK (price_cop >= 0), stock_quantity integer CHECK (stock_quantity >= 0), quote_only boolean NOT NULL DEFAULT false, source_metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_category (product_id uuid NOT NULL REFERENCES product(id) ON DELETE CASCADE, category_id uuid NOT NULL REFERENCES category(id), PRIMARY KEY(product_id, category_id));
CREATE TABLE inventory_adjustment (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES product(id), quantity_before integer, quantity_after integer CHECK (quantity_after >= 0), reason text NOT NULL, actor_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_image (id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES product(id) ON DELETE CASCADE, object_key text, original_url text, position integer NOT NULL DEFAULT 0, CHECK (object_key IS NOT NULL OR original_url IS NOT NULL));
CREATE TABLE admin_user (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_session (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES admin_user(id) ON DELETE CASCADE, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL);
